module ShifterTruncateFP16INTInner(
  input         clock,
                reset,
  output        io_in_ready,
  input         io_in_valid,
  input  [9:0]  io_in_bits_in,
  input  [5:0]  io_in_bits_shift,
  input         io_out_ready,
  output        io_out_valid,
  output [20:0] io_out_bits_out
);

  reg         io_out_rValid;
  reg  [20:0] io_out_rBits_out;
  wire        s0_ready = ~io_out_rValid | io_out_ready;
  always @(posedge clock) begin
    automatic logic _io_out_T;
    _io_out_T = s0_ready & io_in_valid;
    if (reset)
      io_out_rValid <= 1'h0;
    else
      io_out_rValid <= _io_out_T | ~(io_out_ready & io_out_rValid) & io_out_rValid;
    if (_io_out_T) begin
      automatic logic [9:0] _shifted_T =
        $signed($signed(io_in_bits_in) >>> io_in_bits_shift);
      io_out_rBits_out <= {{11{_shifted_T[9]}}, _shifted_T};
    end
  end // always @(posedge)
  assign io_in_ready = s0_ready;
  assign io_out_valid = io_out_rValid;
  assign io_out_bits_out = io_out_rBits_out;
endmodule

